import { Prism, languages } from '../prismCore'
import './javascript'
import './markup-templating'

languages.eta = languages.ejs = {
	'delimiter': {
		pattern: /^<%[-_=]?|[-_]?%>$/,
		alias: 'punctuation'
	},
	'comment': /^#[\s\S]*/,
	'language-javascript': {
		pattern: /[\s\S]+/,
		inside: 'js'
	}
};

Prism.hooks.add('before-tokenize', env => {
	var ejsPattern = /<%(?!%)[\s\S]+?%>/g;
	languages['markup-templating'].buildPlaceholders(env, 'ejs', ejsPattern);
});

Prism.hooks.add('after-tokenize', env => {
	languages['markup-templating'].tokenizePlaceholders(env, 'ejs');
});
